"""Test conversations: per KB entry (generated by the customer model,
one call per entry) and per KB (built from those with fixed turns).
Cached in .local/chat-eval/cases/<kb>.json so every run (and both bot
models) uses the same cases; delete the file to regenerate."""

from __future__ import annotations

import json
import sqlite3
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, Field

from backend.evals.harness import DEMO_DB, OUT

Expected = Literal["answer", "not_covered", "ticket", "polite", "any"]


class Case(BaseModel):
    case_id: str
    kb: str
    kind: str
    entry_id: str | None = None
    opener: str
    # Fixed customer messages for turns 2, 3, ...; the simulator writes the
    # rest (up to `turns`) when `simulate` is true.
    script: list[str] = []
    turns: int = 2
    simulate: bool = True
    persona: str = "a customer of the product"
    goal: str = ""
    expected: Expected = "answer"


class _EntryCases(BaseModel):
    paraphrased: str = Field(description="the entry's question in other words, as a customer writes it")
    vague: str = Field(description="a short, vague message about the same problem, missing key details")
    typo_mixed: str = Field(description="the same question in Tanglish or Hinglish: romanised Tamil or Hindi "
                                        "words mixed with English product words, lower case, with typos and "
                                        "no punctuation, e.g. 'leave apply panna epdi pls steps sollunga' or "
                                        "'payslip kaha milega bhai not showin'")
    direct: str = Field(description="the question asked directly; for a how-to, in how-to form ('how do I ...')")
    pasted_error: str = Field(description="if the entry is about an error or failure: a customer message "
                                          "pasting a plausible error text from the entry; else an empty string")
    near_miss: str = Field(description="a question on a RELATED topic that this entry and its steps do NOT "
                                       "answer (a different task or setting), as a customer asks it")
    goal: str = Field(description="what the customer wants to achieve, in one sentence")


_GENERATE = (
    "You write test messages for a help-desk chat bot. Below is one knowledge-base entry of the product's "
    "help desk. Write realistic customer messages about it, each in the customer's own words (never copy the "
    "entry's sentences), one to three sentences each. Do not mention the knowledge base."
)


def _entry_text(entry: dict) -> str:
    steps = "\n".join(f"{n}. {s['text'] if isinstance(s, dict) else s}"
                      for n, s in enumerate(entry.get("steps") or [], start=1))
    return (f"Title: {entry['title']}\nKind: {entry.get('kind')}\nQuestions: {'; '.join(entry['questions'])}\n"
            f"Answer: {entry.get('answer', '')}\nSteps:\n{steps}")


def generate(kb: str, pack: dict) -> list[Case]:
    from backend.ai_service import backends, provider

    cases: list[Case] = []
    per_entry = []
    for n, entry in enumerate(pack["entries"]):
        with backends.model_task("eval_customer"):
            gen = provider.complete_json(_GENERATE, {"kb_entry": _entry_text(entry)}, _EntryCases,
                                         temperature=0.7, operation="eval_generate")
        per_entry.append((entry, gen))
        eid = entry["kb_entry_id"]
        base = {"kb": kb, "entry_id": eid, "goal": gen.goal}
        # Four per entry: three always, the fourth rotates so each form is covered across the KB.
        fourth = ("pasted_error", gen.pasted_error) if n % 2 and gen.pasted_error else ("direct", gen.direct)
        for kind, text, persona in (
                ("paraphrased", gen.paraphrased, "a polite customer"),
                ("vague", gen.vague, "a customer who gives little detail until asked"),
                ("typo_mixed", gen.typo_mixed, "a busy customer who types fast in Tanglish or Hinglish"),
                (*fourth, "a customer who wants a quick answer")):
            cases.append(Case(case_id=f"{kb}-{eid}-{kind}", kind=kind, opener=text, persona=persona,
                              turns=3, **base))
    cases += _kb_level(kb, per_entry)
    return cases


def _kb_level(kb: str, per_entry: list) -> list[Case]:
    (a, ga), (b, gb) = per_entry[0], per_entry[min(1, len(per_entry) - 1)]
    last, gl = per_entry[-1]
    mid, gm = per_entry[len(per_entry) // 2]
    return [
        Case(case_id=f"{kb}-small_talk", kb=kb, kind="small_talk", entry_id=a["kb_entry_id"], opener="hi",
             script=[ga.paraphrased], turns=4, goal=ga.goal),
        Case(case_id=f"{kb}-topic_switch", kb=kb, kind="topic_switch", entry_id=b["kb_entry_id"],
             opener=ga.direct, script=[f"ok. another thing: {gb.paraphrased}"], turns=4, goal=gb.goal),
        Case(case_id=f"{kb}-near_miss-1", kb=kb, kind="near_miss", opener=ga.near_miss, turns=3,
             expected="not_covered", goal="get an answer to this exact question"),
        Case(case_id=f"{kb}-near_miss-2", kb=kb, kind="near_miss", opener=gl.near_miss, turns=3,
             expected="not_covered", goal="get an answer to this exact question"),
        Case(case_id=f"{kb}-out_of_scope", kb=kb, kind="out_of_scope", opener="who won the cricket match yesterday?",
             script=["ok tell me a joke then"], turns=2, simulate=False, expected="polite"),
        Case(case_id=f"{kb}-angry", kb=kb, kind="angry", entry_id=mid["kb_entry_id"],
             opener=f"this is useless, nothing works!!! {gm.direct}", turns=3,
             persona="an angry, impatient customer who uses CAPS and exclamation marks", goal=gm.goal),
        Case(case_id=f"{kb}-ok_thanks", kb=kb, kind="ok_thanks", entry_id=b["kb_entry_id"], opener=gb.direct,
             script=["ok", "hmm", "thanks"], turns=4, simulate=False, goal=gb.goal),
        Case(case_id=f"{kb}-human", kb=kb, kind="human_request", entry_id=last["kb_entry_id"], opener=gl.vague,
             script=["I want to talk to a human"], turns=2, simulate=False, expected="ticket"),
        Case(case_id=f"{kb}-followup", kb=kb, kind="followup", entry_id=a["kb_entry_id"], opener=ga.direct,
             script=["what next", "steps please", "what are the sources?"], turns=4, simulate=False, goal=ga.goal),
    ]


def load_or_generate(kb: str, pack: dict) -> list[Case]:
    path = OUT / "cases" / f"{kb}.json"
    if path.exists():
        return [Case(**c) for c in json.loads(path.read_text())]
    cases = generate(kb, pack)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps([c.model_dump() for c in cases], indent=1, ensure_ascii=False))
    return cases


def feedback_cases(db_path: Path = DEMO_DB) -> list[Case]:
    """Transcripts saved with "This reply was wrong" (chat_feedback), replayed
    with the customer's messages as written: permanent regression cases."""
    try:
        conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    except sqlite3.Error:
        return []
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute("SELECT feedback_id, transcript FROM chat_feedback WHERE consent = 1").fetchall()
    except sqlite3.Error:   # an older database without the table
        rows = []
    finally:
        conn.close()
    out = []
    for row in rows:
        said = [m["content"] for m in json.loads(row["transcript"]) if m["role"] == "customer"]
        if said:
            out.append(Case(case_id=f"feedback-{row['feedback_id']}", kb="demo", kind="feedback", opener=said[0],
                            script=said[1:], turns=len(said), simulate=False, expected="any"))
    return out
